userId = system.kanoa.security.getIDPUserId(self.session.props.auth.user)
paramsDict = {'userId': userId, 'enabled': True}

viewParams = value
if viewParams.has_key('parentPathList') and len(viewParams['parentPathList'] or []) > 0:
	assets = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.asset.getAssets({'assetPathList': viewParams['parentPathList']}))
	#An enterprise, site or area stands for the assets under it; with includeChildren every listed asset does (e.g. a lot
	#operation linked to Storage happens at Storage\Receiving). Children are matched under a separator, so Machine 1 isn't Machine 10
	includeChildren = viewParams.has_key('includeChildren') and bool(viewParams['includeChildren'])
	assetPathList = []
	for asset in assets:
		assetPathList.append(asset['assetPath'])
		if includeChildren or asset['assetTypeName'].lower() in ('enterprise', 'site', 'area'): assetPathList.append(asset['assetPath'] + '\\%')

	paramsDict['assetPathList'] = assetPathList

assets = system.kanoa.asset.getAssets(paramsDict)
#Tools are left out of asset lists unless asked for (e.g. CMMS work orders on a mold)
if viewParams.has_key('includeTooling') and viewParams['includeTooling']:
	paramsDict['isTooling'] = True
	tools = system.kanoa.asset.getAssets(paramsDict)
	if tools is not None and assets is not None and tools.getRowCount() > 0:
		assets = system.dataset.appendDataset(assets, tools)
#Transports (mobile assets) are left out when they can't be the answer, e.g. where a lot operation happens
if viewParams.has_key('excludeMobile') and viewParams['excludeMobile'] and assets is not None:
	mobile = [i for i in range(assets.getRowCount()) if assets.getValueAt(i, 'mobile')]
	if mobile: assets = system.dataset.deleteRows(assets, mobile)
return assets


if not value.has_key('options'):
	options = {
				"dragDrop": False,
				"expand": False,
				"multiSelect": False,
				"showBreadcrumb": True,
				"showClear": True,
				"showSelectedPath": False
				}
else:
	options = dict(value['options'])

#If we are filtering for specifc assets, we can't use the breadcrumb as the user selection may not exist in the dataset
if value.has_key('parentPathList') and len(value['parentPathList']) > 0:
	options['showBreadcrumb'] = False
	options['showSelectedPath'] = True

return options

