#	system.perspective.print("assetSelector - assetSelected msg rcvd with %s"%payload)
	if payload['selectorId'] is not None and payload['selectorId'] != self.view.custom.selectorId: return

	if payload['activity'] == 'nodeSelected': 
		assetPath = payload['selection'][0]['value']['path'] if len(payload['selection']) > 0 else None
		params = dict(self.view.params.value)
		if not (params.has_key('persistent') and params['persistent'] == False): system.kanoa.utilities.storeAssetPath(self, assetPath)	
		self.view.custom.assetPath = assetPath
		self.view.params.value.assetPath = assetPath
		if params.get('msgHandler'):
			system.perspective.sendMessage(params['msgHandler'], {'assetPath': assetPath}, scope='page')

	if payload['activity'] == 'nodeDropped': system.perspective.print('asset drag and drop done')
	return
